INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM204BHOK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'For the function $f(x) = -2(x + 3)^2 + 17$, what is the maximum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$3$"},{"key":"C","text":"$17$"},{"key":"D","text":"$-17$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function $f(x) = -2(x + 3)^2 + 17$ is in vertex form $a(x - h)^2 + k$ with $a = -2$, $h = -3$, and $k = 17$. Since $a < 0$, the parabola opens downward and the vertex is a maximum. The maximum value is $k = 17$. The distractor $-3$ gives the $x$-coordinate of the vertex rather than the maximum $y$-value. The distractor $3$ is a sign error on the $x$-coordinate of the vertex, confusing $(x + 3)^2$ with $(x - 3)^2$. The distractor $-17$ incorrectly negates the maximum value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM215FYBC', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A delivery service charges a flat fee of \\$37 plus \\$4 per kilogram for express shipments and a flat fee of \\$19 plus \\$7 per kilogram for standard shipments. For what weights, in kilograms, is the express shipment strictly cheaper than the standard shipment?', NULL, $lyceon_json$[{"key":"A","text":"$w > 6$"},{"key":"B","text":"$w < 6$"},{"key":"C","text":"$w > 18$"},{"key":"D","text":"$w < 18$"}]$lyceon_json$::jsonb, 'A', NULL, E'The express cost is $37 + 4w$ and the standard cost is $19 + 7w$. Setting express strictly less: $37 + 4w < 19 + 7w$. Subtracting $4w$ from both sides gives $37 < 19 + 3w$, then $18 < 3w$, so $w > 6$. The option $w < 6$ results from reversing the inequality direction when dividing. The option $w > 18$ comes from failing to divide $18$ by $3$, treating the intermediate value as the answer. The option $w < 18$ combines both errors: using the undivided intermediate and reversing the direction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21THYAI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{3(2x - 11)}{4} + 5 = 17$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{59}{6}$"},{"key":"B","text":"$\\frac{27}{2}$"},{"key":"C","text":"$3$"},{"key":"D","text":"$\\frac{43}{6}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting 5 from both sides gives $\\frac{3(2x - 11)}{4} = 12$. Multiplying both sides by 4 yields $3(2x - 11) = 48$. Dividing by 3 gives $2x - 11 = 16$, so $2x = 27$ and $x = \\frac{27}{2}$. The value $\\frac{59}{6}$ arises from an arithmetic slip when adding 11. The value $3$ comes from stopping after an incomplete simplification or dividing incorrectly. The value $\\frac{43}{6}$ results from failing to multiply by 4 before dividing by 3.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21VDS7A', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $g$ is defined such that $g(3) = 47$ and $g(11) = -17$. For what value of $x$ does $g(x) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{71}{8}$"},{"key":"B","text":"$\\frac{47}{8}$"},{"key":"C","text":"$-\\frac{71}{8}$"},{"key":"D","text":"$\\frac{79}{8}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-17 - 47}{11 - 3} = \\frac{-64}{8} = -8$. Using point-slope form with $(3, 47)$: $g(x) = -8(x - 3) + 47 = -8x + 24 + 47 = -8x + 71$. Setting $g(x) = 0$: $8x = 71$, so $x = \\frac{71}{8}$. The value $\\frac{47}{8}$ comes from dividing only the $y$-value of one point by the slope magnitude, ignoring the intercept calculation. The value $-\\frac{71}{8}$ results from a sign error when solving $-8x + 71 = 0$. The value $\\frac{79}{8}$ arises from an arithmetic slip when computing $24 + 47$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM229B9W4', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A furniture maker has at most \\$1{,}740 to spend on oak and maple boards. Oak boards cost \\$29 each and maple boards cost \\$58 each. If the maker buys $m$ maple boards and $k$ oak boards, which inequality represents this constraint?', NULL, $lyceon_json$[{"key":"A","text":"$29m + 58k \\leq 1740$"},{"key":"B","text":"$29k + 58m \\leq 1740$"},{"key":"C","text":"$29k + 58m \\geq 1740$"},{"key":"D","text":"$29k + 58m < 1740$"}]$lyceon_json$::jsonb, 'B', NULL, E'Oak boards cost \\$29 each and the maker buys $k$ of them, contributing $29k$ to the total. Maple boards cost \\$58 each and the maker buys $m$ of them, contributing $58m$. The total must be at most \\$1,740, so $29k + 58m \\leq 1740$. The option $29m + 58k \\leq 1740$ reverses which variable pairs with which cost. The option using $\\geq$ inverts the direction of the constraint, requiring spending at least \\$1,740 rather than at most. The option using strict $<$ excludes spending exactly \\$1,740, which "at most" permits.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22MXUGZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $7x - 23 = 33$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'C', NULL, E'To solve $7x - 23 = 33$, add $23$ to both sides to get $7x = 56$. Then divide both sides by $7$ to get $x = 8$. The answer is $8$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM237IYXG', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'$$\\frac{2}{x - 3} + \\frac{5}{x + 1} = \\frac{29}{x^2 - 2x - 3}$$ What is the value of $x$ that satisfies the equation above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Note that $x^2 - 2x - 3 = (x - 3)(x + 1)$. Multiplying both sides of the equation by $(x - 3)(x + 1)$ eliminates all denominators: $2(x + 1) + 5(x - 3) = 29$. Expanding gives $2x + 2 + 5x - 15 = 29$, which simplifies to $7x - 13 = 29$. Solving: $7x = 42$, so $x = 6$. Since $x = 6$ does not make any denominator zero ($6 \\neq 3$ and $6 \\neq -1$), it is a valid solution.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23MUJ1J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A sector of a circle has a central angle of $150^\\circ$ and a radius of $6$. The area of this sector can be written as $k\\pi$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'The area of a sector is $A = \\frac{\\theta}{360^\\circ} \\cdot \\pi r^2 = \\frac{150}{360} \\cdot \\pi \\cdot 6^2 = \\frac{5}{12} \\cdot 36\\pi = 15\\pi$. Since the area equals $k\\pi$, the value of $k$ is $15$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM242RUUZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A teacher records quiz scores for $9$ students: $62, 71, 73, 77, 78, 83, 86, 91, 94$. The teacher then removes the lowest score and the highest score. What is the range of the remaining $7$ scores?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20', ARRAY['20'], E'After removing the lowest score ($62$) and the highest score ($94$), the remaining scores are $71, 73, 77, 78, 83, 86, 91$. The range is $91 - 71 = 20$. A common error is computing the range of the original data set ($94 - 62 = 32$) without removing the extreme values.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24LNFIL', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A gym membership costs a one-time enrollment fee of $\\$53$ plus $\\$29$ per month. If $C(m)$ represents the total cost, in dollars, after $m$ months, which of the following is the best interpretation of the number $29$ in the function $C(m) = 29m + 53$?', NULL, $lyceon_json$[{"key":"A","text":"The total cost increases by $\\$29$ for each additional month of membership."},{"key":"B","text":"The total cost of the membership after $29$ months."},{"key":"C","text":"The one-time enrollment fee is $\\$29$."},{"key":"D","text":"The minimum number of months required for the membership."}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $C(m) = 29m + 53$, the coefficient $29$ is the rate of change, representing the amount by which the total cost increases for each additional month of membership. Interpreting $29$ as the total cost after $29$ months confuses the coefficient with an input value. Interpreting $29$ as the enrollment fee confuses it with the constant term $53$. Interpreting $29$ as a minimum number of months misidentifies a cost rate as a quantity constraint.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25CJZCQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $p$ has the equation $5x + 8y = 52$. Line $q$ is perpendicular to line $p$ and passes through the point $(10, 3)$. What is the $x$-coordinate of the point where line $q$ crosses the $x$-axis?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '65/8', ARRAY['65/8', '8.125'], E'Rewriting line $p$ in slope-intercept form: $y = -\\frac{5}{8}x + \\frac{52}{8}$, so the slope of line $p$ is $-\\frac{5}{8}$. The slope of perpendicular line $q$ is the negative reciprocal, $\\frac{8}{5}$. Using point-slope form with $(10, 3)$: $y - 3 = \\frac{8}{5}(x - 10)$, which simplifies to $y = \\frac{8}{5}x - 16 + 3 = \\frac{8}{5}x - 13$. Setting $y = 0$: $\\frac{8}{5}x = 13$, so $x = \\frac{13 \\times 5}{8} = \\frac{65}{8}$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25GBOHV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A box contains cards numbered 1 through 40. Two cards are drawn at random without replacement. What is the probability that the first card drawn is a multiple of 7 and the second card drawn is an even number, given that the first card drawn is odd?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{3}{20} \\times \\dfrac{20}{39}\\)"},{"key":"B","text":"\\(\\dfrac{5}{40} \\times \\dfrac{20}{39}\\)"},{"key":"C","text":"\\(\\dfrac{3}{20} \\times \\dfrac{20}{40}\\)"},{"key":"D","text":"\\(\\dfrac{5}{20} \\times \\dfrac{20}{39}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The multiples of 7 from 1 to 40 are 7, 14, 21, 28, and 35. Among these, the odd multiples of 7 are 7, 21, and 35 — there are 3 of them. Given that the first card is odd, the sample space for the first draw is the 20 odd numbers from 1 to 40, so P(first card is a multiple of 7 | first card is odd) = 3/20. After removing one odd card, 39 cards remain, of which 20 are even, so P(second card is even) = 20/39. The answer is (3/20)(20/39). The distractor using 5/40 counts all multiples of 7 without conditioning on odd and uses the unconditional denominator. The distractor using 20/40 for the second factor fails to account for without-replacement (should be 39, not 40). The distractor using 5/20 incorrectly counts all five multiples of 7 as odd.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26PD71W', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(-3, 11)$ and $(5, -13)$. What is the equation of this line in slope-intercept form?', NULL, $lyceon_json$[{"key":"A","text":"$y = -3x + 2$"},{"key":"B","text":"$y = 3x + 20$"},{"key":"C","text":"$y = -3x - 2$"},{"key":"D","text":"$y = 3x - 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-13 - 11}{5 - (-3)} = \\frac{-24}{8} = -3$. Using point-slope form with $(-3, 11)$: $y - 11 = -3(x + 3)$, which gives $y = -3x - 9 + 11 = -3x + 2$. The equation $y = 3x + 20$ comes from using a positive slope due to a sign error in the numerator. The equation $y = -3x - 2$ results from an arithmetic slip when computing $-9 + 11$. The equation $y = 3x - 2$ arises from both a sign error in the slope and an error in the intercept calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26VVMFB', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For $x \\neq 3$, $x \\neq -7$, and $x \\neq 4$, which of the following is equivalent to $$\\frac{x^2 - 11x + 28}{x^2 - 49} \\cdot \\frac{x^2 + 10x + 21}{x - 4}$$?', NULL, $lyceon_json$[{"key":"A","text":"$x - 3$"},{"key":"B","text":"$x + 3$"},{"key":"C","text":"$\\frac{x + 3}{x + 7}$"},{"key":"D","text":"$\\frac{(x + 3)(x - 7)}{x - 4}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor each polynomial: $x^2 - 11x + 28 = (x - 4)(x - 7)$, $x^2 - 49 = (x - 7)(x + 7)$, and $x^2 + 10x + 21 = (x + 3)(x + 7)$. The expression becomes $\\frac{(x - 4)(x - 7)}{(x - 7)(x + 7)} \\cdot \\frac{(x + 3)(x + 7)}{x - 4}$. Cancelling the common factors $(x - 4)$, $(x - 7)$, and $(x + 7)$ yields $x + 3$. The distractor $x - 3$ arises from a sign error when factoring $x^2 + 10x + 21$. The distractor $\\frac{x + 3}{x + 7}$ results from cancelling $(x - 4)$ and $(x - 7)$ but failing to cancel the $(x + 7)$ factors. The distractor $\\frac{(x + 3)(x - 7)}{x - 4}$ results from incorrectly cancelling only the $(x + 7)$ pair while leaving $(x - 4)$ and $(x - 7)$ uncancelled.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28CZATI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the relationship between the dosage of a supplement, $x$ (in milligrams), and the observed growth rate of bacteria, $y$ (in colonies per hour), using the equation $y = -0.4x^2 + 7.6x - 12.8$ for $2 \\leq x \\leq 16$. According to this model, at what dosage, in milligrams, is the predicted growth rate at its maximum?', NULL, $lyceon_json$[{"key":"A","text":"$7.6$"},{"key":"B","text":"$9.5$"},{"key":"C","text":"$12.8$"},{"key":"D","text":"$3.8$"}]$lyceon_json$::jsonb, 'B', NULL, E'For a quadratic $y = ax^2 + bx + c$ with $a < 0$, the maximum occurs at $x = -\\frac{b}{2a}$. Here, $x = -\\frac{7.6}{2(-0.4)} = -\\frac{7.6}{-0.8} = 9.5$. The distractor $7.6$ is the coefficient $b$ itself, confused with the vertex location. The distractor $12.8$ is the constant term $c$ from the equation, not the $x$-value of the maximum. The distractor $3.8$ results from computing $\\frac{7.6}{2}$ without including the coefficient $a$ in the vertex formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28IHQT6', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'A shipping company charges a base fee of $\\$13$ plus $\\$0.47$ per pound for packages. A second company charges no base fee but $\\$0.84$ per pound. For what weight, in pounds, rounded to the nearest whole number, do the two companies charge the same amount?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '35', ARRAY['35'], E'Setting the costs equal: $13 + 0.47w = 0.84w$. Subtracting $0.47w$ from both sides gives $13 = 0.37w$. Dividing both sides by $0.37$ yields $w = \\frac{13}{0.37} \\approx 35.135$, which rounds to $35$ pounds.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28W5DVW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher wants to estimate the proportion of households in a county that use solar panels. She surveys a random sample of 900 households and finds that 216 use solar panels. The 95% confidence interval for the true proportion is 24% \\(\\pm\\) 2.8%. A second researcher surveys a random sample of 225 households from the same county and also finds that 24% use solar panels. Which of the following statements must be true?', NULL, $lyceon_json$[{"key":"A","text":"The 95% confidence interval from the second survey is approximately 24% \\(\\pm\\) 5.6%."},{"key":"B","text":"The 95% confidence interval from the second survey is approximately 24% \\(\\pm\\) 1.4%."},{"key":"C","text":"The second survey's confidence interval is narrower because it confirmed the first survey's result."},{"key":"D","text":"The two confidence intervals must overlap because they come from the same population."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error is inversely proportional to the square root of the sample size. The second sample has 225 households compared to 900, so it is 1/4 the size. The margin of error scales by sqrt(900)/sqrt(225) = 30/15 = 2, so the second margin is approximately 2.8% x 2 = 5.6%. The distractor of 1.4% incorrectly halves the margin of error, as if a smaller sample produced a smaller margin. The claim that the interval is narrower because the result was confirmed confuses replication with precision — width depends on sample size, not agreement. The statement that the intervals must overlap is not necessarily true; while they likely do in this case, independent samples can produce non-overlapping intervals even from the same population.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28X2H40', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one of the acute angles measures $29^\\circ$ and the hypotenuse has length $18$. Which expression gives the length of the side opposite the $29^\\circ$ angle?', NULL, $lyceon_json$[{"key":"A","text":"$18 \\cos(29^\\circ)$"},{"key":"B","text":"$18 \\sin(29^\\circ)$"},{"key":"C","text":"$\\frac{18}{\\sin(29^\\circ)}$"},{"key":"D","text":"$\\frac{18}{\\cos(29^\\circ)}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sine of an angle equals the ratio of the opposite side to the hypotenuse: $\\sin(29^\\circ) = \\frac{\\text{opposite}}{18}$, so the opposite side is $18 \\sin(29^\\circ)$. The expression $18 \\cos(29^\\circ)$ gives the adjacent side instead, confusing sine and cosine. Dividing $18$ by $\\sin(29^\\circ)$ inverts the relationship and yields a value larger than the hypotenuse, which is impossible for a leg. Dividing $18$ by $\\cos(29^\\circ)$ similarly inverts the cosine ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29T6TYH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $13$ feet and a width of $11$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"$48$"},{"key":"B","text":"$121$"},{"key":"C","text":"$143$"},{"key":"D","text":"$169$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $13 \\times 11 = 143$ square feet. The value $48$ comes from computing the perimeter $2(13 + 11) = 48$ instead of the area, confusing the two formulas. The value $121$ is $11^2$, squaring only the width. The value $169$ is $13^2$, squaring only the length.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29UKXBN', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $(2x + 7)^2 - 4x^2$?', NULL, $lyceon_json$[{"key":"A","text":"$49$"},{"key":"B","text":"$28x + 7$"},{"key":"C","text":"$28x + 49$"},{"key":"D","text":"$8x^2 + 28x + 49$"}]$lyceon_json$::jsonb, 'C', NULL, E'Expanding $(2x + 7)^2$ gives $4x^2 + 28x + 49$. Subtracting $4x^2$ yields $28x + 49$. The distractor $49$ results from omitting the middle term when expanding, treating $(2x + 7)^2$ as $4x^2 + 49$, so the $4x^2$ terms cancel and only $49$ remains. The distractor $28x + 7$ comes from failing to square $7$, writing $7$ instead of $49$. The distractor $8x^2 + 28x + 49$ results from adding $4x^2$ rather than subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AIGB71', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher wanted to determine whether a new tutoring method improves exam scores. She recruited 120 volunteers and randomly assigned 60 to receive the new tutoring method and 60 to receive the standard tutoring method. After 8 weeks, the group using the new method scored an average of 9 points higher on the final exam. Which of the following is a valid conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new tutoring method likely caused the higher exam scores because the study used random assignment."},{"key":"B","text":"The new tutoring method is associated with higher exam scores, but causation cannot be established because the study used volunteers."},{"key":"C","text":"No conclusion can be drawn because 120 participants is too small a sample."},{"key":"D","text":"The results can be generalized to all university students because the study used random assignment."}]$lyceon_json$::jsonb, 'A', NULL, E'Random assignment of participants to treatment and control groups allows the researcher to draw a causal conclusion about the effect of the tutoring method. The distractor claiming only association confuses random assignment (which supports causation) with random sampling (which supports generalization); the use of volunteers limits generalizability but does not prevent causal inference. The distractor about 120 being too small is incorrect — sample size affects precision, not whether a conclusion can be drawn at all, and 120 is a reasonable experimental size. The distractor about generalizing to all university students is wrong because the participants were volunteers, not a random sample of the entire university population, so generalizability is limited.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AO8J8N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at \\$74 is on sale for $35\\%$ off. What is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"\\$25.90"},{"key":"B","text":"\\$39.00"},{"key":"C","text":"\\$48.10"},{"key":"D","text":"\\$59.20"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount is $0.35 \\times 74 = \\$25.90$. The sale price is $74 - 25.90 = \\$48.10$. The distractor \\$25.90 is the discount amount itself, not the sale price. The distractor \\$39.00 comes from an arithmetic error in computing the discount. The distractor \\$59.20 results from applying only $20\\%$ off instead of $35\\%$ off.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C4Q6J6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe calls for $\\frac{7}{3}$ cups of broth for every $13$ servings. If a chef needs to make $39$ servings, how many cups of broth are required?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$\\frac{91}{3}$"},{"key":"C","text":"$\\frac{7}{9}$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $39$ servings is $3$ times $13$ servings, the chef needs $3 \\times \\frac{7}{3} = 7$ cups of broth. The distractor $\\frac{91}{3}$ results from multiplying $\\frac{7}{3} \\times 13$ instead of scaling by the factor of $3$. The distractor $\\frac{7}{9}$ comes from dividing $\\frac{7}{3}$ by $3$ rather than multiplying. The distractor $9$ arises from an arithmetic error in handling the fraction multiplication.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CR32UG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees at a company recorded whether each employee commutes by car or by train and whether they arrive on time or late. Of the 200 employees, 130 commute by car and 70 commute by train. Among car commuters, 91 arrive on time. Among train commuters, 56 arrive on time. Given that a randomly selected employee arrives on time, what is the probability that the employee commutes by train?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{56}{147}\\)"},{"key":"B","text":"\\(\\dfrac{56}{70}\\)"},{"key":"C","text":"\\(\\dfrac{56}{200}\\)"},{"key":"D","text":"\\(\\dfrac{91}{147}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of on-time employees is 91 + 56 = 147. The conditional probability of commuting by train given arriving on time is 56/147. The distractor 56/70 divides by the total train commuters instead of the total on-time employees, confusing P(on time | train) with the requested conditional. The distractor 56/200 divides by the entire survey population, giving the joint probability rather than the conditional probability. The distractor 91/147 gives the probability of commuting by car given on-time arrival, which answers the wrong question.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DFOXNR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, side $AB = 14$, side $BC = 23$, and the angle bisector from vertex $B$ meets side $AC$ at point $D$. By the angle bisector theorem, what is the ratio $\\frac{AD}{DC}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{14}{23}$"},{"key":"B","text":"$\\frac{23}{14}$"},{"key":"C","text":"$\\frac{14}{37}$"},{"key":"D","text":"$\\frac{23}{37}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the angle bisector theorem, the bisector from vertex $B$ divides the opposite side $AC$ so that $\\frac{AD}{DC} = \\frac{AB}{BC} = \\frac{14}{23}$. The inverted ratio $\\frac{23}{14}$ reverses which segment corresponds to which adjacent side, a fundamental misapplication of the theorem. The value $\\frac{14}{37}$ computes $\\frac{AB}{AB + BC}$, which gives the fraction of the whole side $AC$ that is $AD$, rather than the ratio of parts. The value $\\frac{23}{37}$ similarly computes a part-to-whole fraction instead of the requested part-to-part ratio.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DLL0LK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 11 red marbles, 7 blue marbles, and 3 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{7}{21}\\)"},{"key":"B","text":"\\(\\dfrac{7}{14}\\)"},{"key":"C","text":"\\(\\dfrac{3}{21}\\)"},{"key":"D","text":"\\(\\dfrac{11}{21}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is 11 + 7 + 3 = 21. The probability of selecting a blue marble is the number of blue marbles divided by the total: 7/21 (which simplifies to 1/3). The distractor 7/14 results from an arithmetic error in computing the total (using 14 instead of 21). The distractor 3/21 confuses the count of green marbles for blue. The distractor 11/21 gives the probability of red rather than blue.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ET2RH6', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bakery sells croissants for \\$3 each and scones for \\$5 each. On a particular morning, the bakery sold a total of 47 pastries and collected \\$179 in revenue from croissants and scones only. How many scones were sold?', NULL, $lyceon_json$[{"key":"A","text":"$19$"},{"key":"B","text":"$28$"},{"key":"C","text":"$31$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $c$ be the number of croissants and $s$ the number of scones. From the problem: $c + s = 47$ and $3c + 5s = 179$. From the first equation, $c = 47 - s$. Substituting: $3(47 - s) + 5s = 179$, which gives $141 - 3s + 5s = 179$, so $2s = 38$ and $s = 19$. The value $28$ is the number of croissants, not scones, answering for the wrong variable. The value $31$ arises from incorrectly setting up the revenue equation (e.g., swapping the prices). The value $22$ results from an arithmetic slip such as computing $179 - 141 = 36$ instead of $38$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ETLPS5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 registered voters in a city found that 58% support a proposed park renovation. The margin of error for the survey is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between 54% and 62% of all registered voters in the city likely support the park renovation."},{"key":"B","text":"Exactly 58% of all registered voters in the city support the park renovation."},{"key":"C","text":"Between 54% and 62% of the 250 voters surveyed support the park renovation."},{"key":"D","text":"The percentage of voters who support the renovation will increase by 4% over time."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of 4 percentage points means the plausible range for the population parameter is 58% minus 4% to 58% plus 4%, or 54% to 62%. This interval estimates the proportion of all registered voters in the city. The distractor stating exactly 58% ignores the margin of error entirely. The distractor applying the interval to the sample rather than the population misunderstands that the margin of error is about generalizing to the population. The distractor about a 4% increase over time misinterprets the margin of error as a trend.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FLXVQ9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the age of a car, $x$ (in years), and its resale value, $y$ (in thousands of dollars). The line of best fit is $y = -2.7x + 31.4$. According to this model, what is the predicted resale value, in thousands of dollars, of a car that is $6$ years old?', NULL, $lyceon_json$[{"key":"A","text":"$15.2$"},{"key":"B","text":"$14.6$"},{"key":"C","text":"$47.6$"},{"key":"D","text":"$16.2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 6$: $y = -2.7(6) + 31.4 = -16.2 + 31.4 = 15.2$. The distractor $14.6$ comes from a rounding or multiplication error, such as using $-2.8$ instead of $-2.7$. The distractor $47.6$ results from adding $16.2$ to $31.4$ instead of subtracting, a sign error on the negative slope. The distractor $16.2$ is the absolute value of the product $2.7 \\times 6$, representing only a partial computation without adding the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G2B2VA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up an item by $60\\%$ above its wholesale cost, then offers a promotional discount of $25\\%$ off the marked price. If the store sells the item for \\$43.20, what was the wholesale cost?', NULL, $lyceon_json$[{"key":"A","text":"\\$36.00"},{"key":"B","text":"\\$28.80"},{"key":"C","text":"\\$33.23"},{"key":"D","text":"\\$46.08"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $c$ be the wholesale cost. The marked price is $1.60c$. After a $25\\%$ discount, the selling price is $0.75 \\times 1.60c = 1.20c$. Setting $1.20c = 43.20$ gives $c = 36.00$. The distractor \\$28.80 comes from dividing \\$43.20 by $1.50$, as if the net markup were $50\\%$. The distractor \\$33.23 results from dividing \\$43.20 by $1.30$, treating the net effect as a $30\\%$ increase. The distractor \\$46.08 arises from multiplying \\$43.20 by a factor greater than $1$, misunderstanding which direction to undo the discount.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GBLF7Q', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The system of equations below has two solutions. $$y = x^2 - 5x + 3$$ $$y = 2x - 9$$ Which of the following is one of the solutions?', NULL, $lyceon_json$[{"key":"A","text":"$(3, -3)$"},{"key":"B","text":"$(3, 3)$"},{"key":"C","text":"$(4, 3)$"},{"key":"D","text":"$(7, 5)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $x^2 - 5x + 3 = 2x - 9$, which simplifies to $x^2 - 7x + 12 = 0$. Factoring gives $(x - 3)(x - 4) = 0$, so $x = 3$ or $x = 4$. Substituting $x = 3$ into $y = 2x - 9$ yields $y = 6 - 9 = -3$, giving the solution $(3, -3)$. The distractor $(3, 3)$ has the correct $x$-coordinate but a sign error on $y$. The distractor $(4, 3)$ uses the other valid $x$-value but computes $y$ incorrectly; substituting $x = 4$ into $y = 2x - 9$ gives $y = -1$, not $3$. The distractor $(7, 5)$ satisfies the linear equation ($2(7) - 9 = 5$) but not the quadratic ($49 - 35 + 3 = 17 \\neq 5$), reflecting an error in setting up the system.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HDNKXN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values $12, 15, 15, 18, 21, 25, 31$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$18$"},{"key":"C","text":"$19.57$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set $12, 15, 15, 18, 21, 25, 31$ has $7$ values, which are already in order. The median is the middle value, which is the 4th value: $18$. The median is $18$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HTLNPJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'After a $12\\%$ increase, the population of a town is $6{,}272$. What was the population before the increase?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5600', ARRAY['5600'], E'Let $p$ be the original population. After a $12\\%$ increase, the population is $1.12p = 6{,}272$. Dividing both sides by $1.12$: $p = \\frac{6272}{1.12} = 5{,}600$. A common error is computing $6272 - 0.12 \\times 6272 = 5519.36$, which incorrectly takes $12\\%$ of the new population rather than recognizing that $6{,}272$ is $112\\%$ of the original.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J1KQWQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer produces $43$ pages in $4$ minutes. At this constant rate, how many pages does the printer produce in $20$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$172$"},{"key":"B","text":"$180$"},{"key":"C","text":"$200$"},{"key":"D","text":"$215$"}]$lyceon_json$::jsonb, 'D', NULL, E'The rate is $\\frac{43}{4}$ pages per minute, which equals $10.75$ pages per minute. In $20$ minutes, the printer produces $10.75 \\times 20 = 215$ pages. The answer is $215$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JUJMUJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health magazine reported that people who eat breakfast daily have lower rates of heart disease than those who skip breakfast. The study collected data by surveying 3,000 adults about their eating habits and medical histories. Which of the following is the most appropriate conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"There is an association between eating breakfast daily and lower rates of heart disease."},{"key":"B","text":"Eating breakfast daily causes lower rates of heart disease."},{"key":"C","text":"Skipping breakfast causes higher rates of heart disease."},{"key":"D","text":"If the 3,000 adults started eating breakfast daily, their heart disease rates would decrease."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the study is observational (a survey about habits and medical histories, with no random assignment to treatment groups), it can only establish an association, not a causal relationship. The distractor claiming breakfast causes lower heart disease rates incorrectly infers causation from an observational study. Similarly, the distractor claiming skipping breakfast causes higher rates makes the same causal error in the opposite direction. The distractor predicting decreased heart disease if participants changed their behavior assumes a causal relationship that an observational study cannot establish, since confounding variables (exercise, income, overall diet) may explain the observed difference.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
