INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LDOGPW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $50$ values has a mean of $138$ and a median of $131$. Every value in the data set is increased by $7$, and then each result is multiplied by $3$. What is the new median of the transformed data set?', NULL, $lyceon_json$[{"key":"A","text":"$414$"},{"key":"B","text":"$435$"},{"key":"C","text":"$393$"},{"key":"D","text":"$400$"}]$lyceon_json$::jsonb, 'A', NULL, E'When every value is increased by $7$, the median becomes $131 + 7 = 138$. When every value is then multiplied by $3$, the median becomes $138 \\times 3 = 414$. The distractor $435$ applies the transformations to the mean instead of the median: $(138 + 7) \\times 3 = 435$. The distractor $393$ results from multiplying the original median by $3$ without adding $7$ first: $131 \\times 3 = 393$. The distractor $400$ comes from computing $131 \\times 3 + 7 = 400$, applying the addition after the multiplication instead of before.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LLVRX5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Two independent random samples are taken from the same population. Sample A consists of 400 people and finds that 47% prefer Brand X. Sample B consists of 1,600 people and finds that 51% prefer Brand X. The margin of error for Sample A is approximately 5 percentage points. Which of the following best compares the margins of error of the two samples?', NULL, $lyceon_json$[{"key":"A","text":"The margin of error for Sample B is approximately 2.5 percentage points."},{"key":"B","text":"The margin of error for Sample B is approximately 5 percentage points."},{"key":"C","text":"The margin of error for Sample B is approximately 1.25 percentage points."},{"key":"D","text":"The margin of error for Sample B is approximately 10 percentage points."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error is inversely proportional to the square root of the sample size. Since Sample B is 4 times larger than Sample A (1,600 vs. 400), the margin of error for Sample B is approximately 5 / sqrt(4) = 5 / 2 = 2.5 percentage points. The distractor of 5 percentage points assumes the margin of error is the same regardless of sample size. The distractor of 1.25 percentage points incorrectly divides by 4 instead of by sqrt(4). The distractor of 10 percentage points reverses the relationship, suggesting larger samples have larger margins of error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LM1RU0', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $g$ is defined by $g(x) = x^3 - 4x + 11$. What is the value of $g(-2)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Substituting $x = -2$ into $g(x) = x^3 - 4x + 11$ gives $g(-2) = (-2)^3 - 4(-2) + 11 = -8 + 8 + 11 = 11$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MM1IQ3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours studied, $x$, and the score on a test, $y$. The line of best fit for the data is $y = 11x + 37$. What does the slope of this line represent?', NULL, $lyceon_json$[{"key":"A","text":"The predicted test score when no hours are studied"},{"key":"B","text":"The predicted increase in test score for each additional hour studied"},{"key":"C","text":"The total number of hours studied"},{"key":"D","text":"The average test score across all students"}]$lyceon_json$::jsonb, 'B', NULL, E'In the equation $y = 11x + 37$, the slope is $11$, which represents the predicted increase in test score for each additional hour studied. The option describing the predicted score when no hours are studied confuses the slope with the $y$-intercept ($37$). The option about the total hours studied and the option about the average score across all students do not describe the meaning of the slope in a linear model.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MSYNJP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions of $x^2 + 2x - 63 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -9$ and $x = 7$"},{"key":"B","text":"$x = 9$ and $x = -7$"},{"key":"C","text":"$x = -9$ and $x = -7$"},{"key":"D","text":"$x = 3$ and $x = -21$"}]$lyceon_json$::jsonb, 'A', NULL, E'The equation $x^2 + 2x - 63 = 0$ factors as $(x + 9)(x - 7) = 0$ because $9 \\times (-7) = -63$ and $9 + (-7) = 2$. Setting each factor equal to zero gives $x = -9$ and $x = 7$. The distractor $x = 9$ and $x = -7$ reverses the signs of both solutions. The distractor $x = -9$ and $x = -7$ uses the correct factor pair magnitudes but assigns both a negative sign, which would produce a positive constant term and positive linear coefficient. The distractor $x = 3$ and $x = -21$ uses a factor pair whose product is $-63$ but whose sum is $-18$, not $2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O1Y1BQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A chemist mixes Solution X, which contains $23\\%$ acid by volume, with Solution Y, which contains $41\\%$ acid by volume. If the chemist uses $170$ milliliters of Solution X, how many milliliters of Solution Y must be added so that the resulting mixture is $29\\%$ acid by volume?', NULL, $lyceon_json$[{"key":"A","text":"$85$"},{"key":"B","text":"$102$"},{"key":"C","text":"$68$"},{"key":"D","text":"$130$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $y$ be the milliliters of Solution Y. The total acid is $0.23(170) + 0.41y$, and the total volume is $170 + y$. Setting the mixture concentration to $29\\%$: $$\\frac{0.23(170) + 0.41y}{170 + y} = 0.29.$$ This gives $39.1 + 0.41y = 49.3 + 0.29y$, so $0.12y = 10.2$ and $y = 85$. The distractor $102$ results from setting up the equation as $0.23(170) + 0.41y = 0.29 \\times 170$ without accounting for the changing total volume. The distractor $68$ comes from computing $29\\% - 23\\% = 6\\%$ and applying an incorrect proportion. The distractor $130$ arises from inverting the ratio of concentration differences.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O6SHLW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tested a new migraine medication. They randomly selected 500 adults from a national registry of migraine patients and randomly assigned 250 to receive the medication and 250 to receive a placebo. After 12 weeks, the medication group reported 37% fewer migraine days per month on average compared to the placebo group. Which of the following conclusions is best supported by the study design?', NULL, $lyceon_json$[{"key":"A","text":"The medication likely causes a reduction in migraine days, and this result can be generalized to the population of adults with migraines."},{"key":"B","text":"The medication likely causes a reduction in migraine days, but the result cannot be generalized beyond the 500 participants."},{"key":"C","text":"The medication is associated with fewer migraine days, but a causal relationship cannot be established."},{"key":"D","text":"The medication likely causes a reduction in migraine days, and this result can be generalized to all adults, including those without migraines."}]$lyceon_json$::jsonb, 'A', NULL, E'This study uses both random selection (from a national registry of migraine patients) and random assignment (to medication or placebo groups). Random assignment supports a causal conclusion, and random selection from the registry supports generalization to the population of adults with migraines. The distractor that limits generalization to the 500 participants ignores that random selection was used, which supports inference to the broader population. The distractor claiming only association fails to recognize that random assignment enables causal inference. The distractor generalizing to all adults, including those without migraines, extends the conclusion beyond the study''s sampling frame, which was restricted to migraine patients.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O8DLBU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylindrical water tank has a radius of $7$ meters and a height of $9$ meters. The volume of the tank can be written as $k\\pi$ cubic meters. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '441', ARRAY['441'], E'The volume of a cylinder is $V = \\pi r^2 h = \\pi (7)^2 (9) = \\pi \\cdot 49 \\cdot 9 = 441\\pi$ cubic meters. Since the volume equals $k\\pi$, the value of $k$ is $441$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
