INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q8WWUG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, angle $P$ measures $38^\\circ$ and angle $Q$ measures $71^\\circ$. What is the measure, in degrees, of the exterior angle at vertex $R$?', NULL, $lyceon_json$[{"key":"A","text":"$71^\\circ$"},{"key":"B","text":"$109^\\circ$"},{"key":"C","text":"$142^\\circ$"},{"key":"D","text":"$251^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The exterior angle at a vertex of a triangle equals the sum of the two non-adjacent interior angles: $38^\\circ + 71^\\circ = 109^\\circ$. Equivalently, the interior angle at $R$ is $180^\\circ - 38^\\circ - 71^\\circ = 71^\\circ$, and the exterior angle is $180^\\circ - 71^\\circ = 109^\\circ$. The value $71^\\circ$ gives only the interior angle at $R$, stopping short of finding the exterior angle. The value $142^\\circ$ doubles the interior angle ($2 \\times 71$), misapplying the relationship. The value $251^\\circ$ adds $180^\\circ$ to the interior angle rather than subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QUEZGP', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{6x^2 + 19x - 7}{2x + 7}$ for $x \\neq -\\frac{7}{2}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 1$"},{"key":"B","text":"$3x - 1$"},{"key":"C","text":"$6x - 1$"},{"key":"D","text":"$3x^2 - 1$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator: $6x^2 + 19x - 7$. Find two numbers whose product is $6 \\times (-7) = -42$ and whose sum is $19$: these are $21$ and $-2$. Rewrite as $6x^2 + 21x - 2x - 7 = 3x(2x + 7) - 1(2x + 7) = (3x - 1)(2x + 7)$. Dividing by $(2x + 7)$ gives $3x - 1$. The distractor $3x + 1$ has the wrong sign on the constant, from a sign error in the factoring step. The distractor $6x - 1$ results from dividing only the $x$ term of the numerator by the leading coefficient of the denominator. The distractor $3x^2 - 1$ reflects incomplete simplification, retaining the squared term rather than completing the polynomial division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QWXGEL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cone has a slant height of $26$ cm and a base radius of $10$ cm. What is the volume of the cone, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$80\\pi$"},{"key":"B","text":"$800\\pi$"},{"key":"C","text":"$\\frac{2600\\pi}{3}$"},{"key":"D","text":"$2400\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'First find the height using the Pythagorean theorem: $h = \\sqrt{26^2 - 10^2} = \\sqrt{676 - 100} = \\sqrt{576} = 24$ cm. The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(10)^2(24) = \\frac{2400\\pi}{3} = 800\\pi$ cubic centimeters. The value $80\\pi$ results from using $r$ instead of $r^2$ in the formula: $\\frac{1}{3}\\pi(10)(24) = 80\\pi$. The value $\\frac{2600\\pi}{3}$ uses the slant height $26$ directly as the cone height instead of computing the actual height via the Pythagorean theorem: $\\frac{1}{3}\\pi(100)(26) = \\frac{2600\\pi}{3}$. The value $2400\\pi$ omits the $\\frac{1}{3}$ factor entirely: $\\pi(100)(24) = 2400\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QYLXZQ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $7x - 13 > 22$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'D', NULL, E'Solving $7x - 13 > 22$ gives $7x > 35$, so $x > 5$. The value $6$ is the only option greater than $5$. The value $5$ fails because the inequality is strict ($>$, not $\\geq$), so $5$ is not included. The value $4$ results from an arithmetic error such as dividing $35$ by $7$ incorrectly. The value $3$ reflects a fundamental misunderstanding of the inequality''s solution set.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VC3GJB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 10x + 14y + 23 = 0$. What is the length of the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{23}$"},{"key":"B","text":"$\\sqrt{37}$"},{"key":"C","text":"$\\sqrt{51}$"},{"key":"D","text":"$\\sqrt{74}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Complete the square: rewrite as $(x^2 - 10x) + (y^2 + 14y) = -23$. For the $x$ terms, add $25$: $(x - 5)^2$. For the $y$ terms, add $49$: $(y + 7)^2$. This gives $(x - 5)^2 + (y + 7)^2 = -23 + 25 + 49 = 51$. So $r^2 = 51$ and $r = \\sqrt{51}$. The value $\\sqrt{23}$ treats the constant $23$ directly as $r^2$ without completing the square. The value $\\sqrt{37}$ results from an arithmetic error when combining $-23 + 25 + 49$ (e.g., computing $-23 + 11 + 49 = 37$). The value $\\sqrt{74}$ adds $25 + 49 = 74$ but omits subtracting $23$ from the right side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VYQ3D9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles are supplementary. If one angle measures $47^\\circ$, what is the measure, in degrees, of the other angle?', NULL, $lyceon_json$[{"key":"A","text":"$43^\\circ$"},{"key":"B","text":"$133^\\circ$"},{"key":"C","text":"$137^\\circ$"},{"key":"D","text":"$313^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'Supplementary angles sum to $180^\\circ$. The other angle is $180^\\circ - 47^\\circ = 133^\\circ$. The value $43^\\circ$ results from confusing supplementary with complementary angles, which sum to $90^\\circ$ ($90 - 47 = 43$). The value $137^\\circ$ is an arithmetic slip in subtracting $47$ from $180$. The value $313^\\circ$ comes from subtracting from $360^\\circ$ instead of $180^\\circ$ ($360 - 47 = 313$).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W0M4YF', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $8x - 3y = 24$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$3$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting $x = 0$ into $8x - 3y = 24$ gives $-3y = 24$, so $y = -8$. The $y$-intercept is $-8$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WIDXB5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $34$ centimeters. What is the circumference of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$17\\pi$ cm"},{"key":"B","text":"$34\\pi$ cm"},{"key":"C","text":"$68\\pi$ cm"},{"key":"D","text":"$289\\pi$ cm"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference formula is $C = \\pi d = 34\\pi$ cm. The value $17\\pi$ uses the radius ($17$) with the incorrect formula $C = \\pi r$ instead of $C = 2\\pi r$, halving the correct answer. The value $68\\pi$ incorrectly doubles the diameter before multiplying by $\\pi$. The value $289\\pi$ applies the area formula $\\pi r^2 = \\pi(17)^2 = 289\\pi$ instead of the circumference formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WM7Z3A', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 13x - 41$. What is the value of $f(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$24$"},{"key":"C","text":"$26$"},{"key":"D","text":"$106$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 5$ into $f(x) = 13x - 41$ gives $f(5) = 13(5) - 41 = 65 - 41 = 24$. The value is $24$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XP4RCP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'A ladder leans against a vertical wall, making an angle of $67^\\circ$ with the ground. The foot of the ladder is $4.7$ meters from the base of the wall. What is the length of the ladder, in meters, rounded to the nearest tenth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'The angle between the ladder and the ground is $67^\\circ$, and the horizontal distance from the wall ($4.7$ m) is the side adjacent to this angle. The ladder is the hypotenuse. Using $\\cos(67^\\circ) = \\frac{4.7}{L}$ gives $L = \\frac{4.7}{\\cos(67^\\circ)}$. Since $\\cos(67^\\circ) \\approx 0.3907$, the ladder length is $\\frac{4.7}{0.3907} \\approx 12.03$, which rounds to $12.0$ meters.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y6OHYJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The polynomial function $p$ is defined by $p(x) = x^3 - 9x^2 + 23x - 15$. It is known that $p(1) = 0$. Which of the following correctly expresses $p(x)$ as a product of three linear factors?', NULL, $lyceon_json$[{"key":"A","text":"$(x - 1)(x - 3)(x - 5)$"},{"key":"B","text":"$(x + 1)(x + 3)(x + 5)$"},{"key":"C","text":"$(x - 1)(x - 5)(x + 3)$"},{"key":"D","text":"$(x - 1)(x^2 - 8x + 15)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $p(1) = 0$, $(x - 1)$ is a factor. Performing polynomial division: $\\frac{x^3 - 9x^2 + 23x - 15}{x - 1} = x^2 - 8x + 15$. Factoring $x^2 - 8x + 15$: we need two numbers whose product is $15$ and whose sum is $-8$, which are $-3$ and $-5$. So $x^2 - 8x + 15 = (x - 3)(x - 5)$, and $p(x) = (x - 1)(x - 3)(x - 5)$. The distractor $(x + 1)(x + 3)(x + 5)$ reverses all signs, producing $x^3 + 9x^2 + 23x + 15$. The distractor $(x - 1)(x - 5)(x + 3)$ has a sign error on the factor $(x - 3)$, yielding $(x - 1)(x^2 - 2x - 15) = x^3 - 3x^2 - 13x + 15$, which is not the original polynomial. The distractor $(x - 1)(x^2 - 8x + 15)$ is a correct but incomplete factorization — it does not express $p(x)$ as a product of three linear factors as the question requires.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZDRIGH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'From the top of a $53$-meter cliff, the angle of depression to a boat at sea is $19^\\circ$. From the same point, the angle of depression to a second boat, which is directly beyond the first boat along the same line from the cliff base, is $11^\\circ$. What is the distance, in meters, between the two boats?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{53}{\\tan(11^\\circ)} - \\frac{53}{\\tan(19^\\circ)}$"},{"key":"B","text":"$\\frac{53}{\\tan(19^\\circ)} - \\frac{53}{\\tan(11^\\circ)}$"},{"key":"C","text":"$53\\tan(19^\\circ) - 53\\tan(11^\\circ)$"},{"key":"D","text":"$53(\\tan(19^\\circ) + \\tan(11^\\circ))$"}]$lyceon_json$::jsonb, 'A', NULL, E'For the closer boat (depression angle $19^\\circ$), the horizontal distance from the cliff base is $d_1 = \\frac{53}{\\tan(19^\\circ)}$. For the farther boat (depression angle $11^\\circ$, smaller because the boat is farther), the distance is $d_2 = \\frac{53}{\\tan(11^\\circ)}$. The gap between boats is $d_2 - d_1 = \\frac{53}{\\tan(11^\\circ)} - \\frac{53}{\\tan(19^\\circ)}$. Reversing the subtraction order yields a negative value, a sign error. Using $53\\tan(\\theta)$ instead of $\\frac{53}{\\tan(\\theta)}$ inverts the tangent ratio (confusing opposite/adjacent with adjacent/opposite). Adding the tangent terms conflates the two distances rather than finding their difference.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2069EY5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The playwright Lorraine Hansberry drew extensively on her family''s legal battles against racially restrictive housing covenants in 1940s Chicago when crafting her most celebrated work, A Raisin in the Sun. ________ Hansberry''s dramaturgy was not merely autobiographical; she wove together sociological research on urban displacement, the existentialist philosophy she encountered through Simone de Beauvoir''s writings, and West African storytelling traditions to construct a layered narrative that transcended any single source of inspiration.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"For instance,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"In addition,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence establishes that Hansberry drew extensively on personal family experience. The second sentence introduces a contrasting point: her work was not merely autobiographical but incorporated multiple other intellectual and cultural sources. This contrast requires a concession or contradiction transition. "Nevertheless" correctly signals that the second sentence qualifies or counters the impression left by the first. "Similarly" would incorrectly suggest the second sentence presents a parallel idea, when it actually introduces a complication. "For instance" would incorrectly frame the second sentence as an example of the first, but the second sentence challenges rather than illustrates the first sentence''s claim. "In addition" would incorrectly suggest the second sentence simply adds a compatible point, missing the pivotal shift from autobiography to broader intellectual synthesis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW206LI46', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit fly Drosophila melanogaster has been a model organism in genetics research for over a century, in part because of its rapid reproductive cycle — a female can produce hundreds of offspring in just ten days. Researchers have also valued the species because its genome contains approximately 14,000 genes, roughly 60 percent of which have recognizable counterparts in the human genome. This genetic overlap means that ________', $lyceon_json$[{"key":"A","text":"fruit flies reproduce more quickly than any other insect used in laboratory research."},{"key":"B","text":"discoveries about gene function in fruit flies can often provide insights relevant to human biology."},{"key":"C","text":"the human genome is less complex than scientists originally predicted before it was fully sequenced."},{"key":"D","text":"fruit flies and humans diverged from a common ancestor more recently than other model organisms did."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes that fruit flies share about 60 percent of their genes with humans and frames this as a reason researchers value the species. The logical completion is that this genetic overlap makes fruit fly research applicable to understanding human biology. The option about reproductive speed restates an earlier detail and does not follow from the specific point about genetic overlap. The option about human genome complexity introduces a claim about sequencing expectations that the passage does not set up. The option about recent evolutionary divergence makes a specific phylogenetic claim that does not logically follow from the percentage of shared genes alone.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21DV1QM', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'During the 1970s, the economist Yuliana Petrov studied labor migration patterns in rural _______ her analysis revealed that seasonal workers who relocated to industrial centers for more than eleven months rarely returned to agricultural employment, even when crop yields in their home provinces improved substantially.', $lyceon_json$[{"key":"A","text":"Bulgaria: drawing on census data from forty-seven villages,"},{"key":"B","text":"Bulgaria, drawing on census data from forty-seven villages;"},{"key":"C","text":"Bulgaria drawing on census data from forty-seven villages,"},{"key":"D","text":"Bulgaria. Drawing on census data from forty-seven villages,"}]$lyceon_json$::jsonb, 'D', NULL, E'Two independent clauses need proper separation here. The participial phrase ''Drawing on census data from forty-seven villages'' modifies the subject of the second clause (''her analysis''). Starting a new sentence with this participial phrase properly separates the independent clauses while attaching the modifier to the correct subject. Using a colon after ''Bulgaria'' followed by the participial phrase and a comma would require what follows the colon to elaborate on or specify ''rural Bulgaria,'' but instead the phrase modifies ''her analysis,'' creating a structural mismatch. Using a comma after ''Bulgaria'' and a semicolon after ''villages'' improperly splits the participial phrase from the clause it modifies, severing the modifier from its subject. Omitting all punctuation after ''Bulgaria'' creates a run-on by failing to mark any boundary between the first independent clause and the participial phrase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21EBOFA', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Tromsø have documented that Arctic foxes can traverse sea ice for distances exceeding 3,500 kilometers during a single migration. ________ the foxes'' remarkable endurance allows them to colonize remote islands that would otherwise be inaccessible to terrestrial predators.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"On the contrary,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence presents a result that follows from the foxes'' ability to travel extreme distances across sea ice: because they can cover such vast distances, they can reach and colonize remote islands. This cause-and-effect relationship requires a consequence transition. "Consequently" correctly signals that the colonization of remote islands is a result of the foxes'' endurance. "In other words" would incorrectly signal a restatement, but the second sentence adds new information rather than rephrasing the first. "On the contrary" would incorrectly signal a contradiction between two ideas that are logically aligned. "Meanwhile" would incorrectly suggest two simultaneous but unrelated events, when in fact the second sentence follows directly from the first.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21GFWV2', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if true, would most directly undermine the researchers'' conclusion?', E'A team of behavioral economists conducted a study in which 340 participants were given a hypothetical budget of \\$1,200 and asked to allocate it between a savings account and immediate consumer purchases. Participants were randomly assigned to one of two conditions: in the "future self" condition, participants viewed digitally aged photographs of themselves before making their allocation decisions, while in the control condition, participants viewed current photographs. The researchers found that participants in the future-self condition allocated an average of \\$417 to savings, compared with \\$268 in the control group. The researchers concluded that vividly imagining one''s future self increases the psychological weight people assign to long-term financial outcomes, thereby promoting saving behavior.', $lyceon_json$[{"key":"A","text":"Participants in the future-self condition reported significantly higher levels of anxiety about aging than control participants, and those with the highest anxiety scores also allocated the most to savings."},{"key":"B","text":"A follow-up study using real monetary stakes of \\$50 replicated the direction of the effect but found a smaller difference between conditions."},{"key":"C","text":"Participants who viewed aged photographs of a stranger rather than of themselves allocated amounts to savings comparable to those in the future-self condition."},{"key":"D","text":"Demographic analysis showed that participants over age 45 allocated more to savings than younger participants regardless of experimental condition."}]$lyceon_json$::jsonb, 'C', NULL, E'The researchers concluded that imagining one''s own future self increases the weight assigned to long-term outcomes. If viewing aged photographs of a stranger produced the same savings increase, this would suggest the effect is driven by a general emotional response to aging imagery rather than by identification with one''s personal future — directly undermining the proposed mechanism. The finding about anxiety and aging is consistent with the researchers'' conclusion because higher anxiety about one''s own aging could be part of the mechanism by which future-self visualization promotes saving. The follow-up study with smaller real stakes actually supports the conclusion by replicating the direction of the effect. The demographic finding about older participants saving more addresses a different variable (actual age) and does not speak to the causal mechanism the researchers proposed.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24955ML', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 1847, the Hungarian physician Ignaz Semmelweis observed that the mortality rate among women delivering babies in the physician-staffed ward of Vienna General Hospital was nearly five times higher than in the midwife-staffed ward. After his colleague Jakob Kolletschka died from a wound infection contracted during an autopsy, Semmelweis hypothesized that physicians were transferring "cadaverous particles" from dissection rooms to the maternity ward. He instituted a policy requiring physicians to wash their hands in a chlorinated lime solution before examining patients. Within months, the mortality rate in the physician-staffed ward fell from 18.3 percent to 1.9 percent. Despite this dramatic evidence, Semmelweis''s theory was largely rejected by the medical establishment, which considered the idea that physicians themselves could be agents of disease to be offensive and implausible.', $lyceon_json$[{"key":"A","text":"Semmelweis identified a cause of high maternal mortality and demonstrated an effective prevention, but his findings were dismissed by contemporary physicians."},{"key":"B","text":"The discovery of chlorinated lime as a disinfectant in the 1840s transformed hospital sanitation practices across Europe."},{"key":"C","text":"Midwives in nineteenth-century Vienna provided safer childbirth care than physicians because they followed stricter hygiene protocols."},{"key":"D","text":"Semmelweis's colleague Jakob Kolletschka played a crucial role in developing the germ theory of disease."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces Semmelweis''s observation, hypothesis, intervention, and the medical establishment''s rejection of his findings. The correct answer captures all of these elements. The option about chlorinated lime transforming European sanitation goes beyond the passage, which describes only one hospital and notes that the findings were rejected, not widely adopted. The option about midwives following stricter hygiene protocols misreads the passage — the text states that midwives had lower mortality rates but does not attribute this to stricter hygiene protocols on their part. The option about Kolletschka developing germ theory misrepresents his role; his death merely prompted Semmelweis''s hypothesis, and the passage does not credit Kolletschka with theoretical contributions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25XRI0R', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Ecologist Suzanne Simard''s research on mycorrhizal networks — underground fungal systems that connect the roots of trees — has challenged the longstanding view that forest trees compete primarily as isolated individuals. Simard demonstrated that Douglas fir and paper birch trees exchange carbon through these fungal connections, with the direction and magnitude of transfer shifting seasonally: birch trees, which leaf out earlier, supply carbon to shaded fir seedlings in spring, while firs reciprocate in autumn when birches have shed their leaves. Critically, Simard found that older "mother trees" preferentially channel resources to their own offspring over unrelated seedlings, suggesting that kin recognition operates through the network. However, some forest ecologists have cautioned that the ecological significance of these transfers remains uncertain, noting that the quantities of carbon exchanged may be too small to meaningfully affect tree survival under natural conditions.', $lyceon_json$[{"key":"A","text":"Simard's research reveals that trees engage in resource sharing through fungal networks, but the importance of this sharing for tree survival is debated among ecologists."},{"key":"B","text":"Mycorrhizal networks allow mother trees to ensure the survival of their offspring by directing all available nutrients toward genetically related seedlings."},{"key":"C","text":"Simard's findings have conclusively overturned the competition-based model of forest ecology in favor of a cooperative model."},{"key":"D","text":"The seasonal exchange of carbon between Douglas fir and paper birch is the primary mechanism by which temperate forests maintain biodiversity."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Simard''s findings about resource sharing through mycorrhizal networks and then introduces skepticism about whether these transfers are ecologically significant. The correct answer captures both the discovery and the ongoing debate. The option about mother trees directing all nutrients to offspring overstates the finding — the passage says mother trees "preferentially channel resources" to kin, not that they direct all nutrients exclusively. The option claiming Simard conclusively overturned the competition model contradicts the passage, which notes that other ecologists question the significance of the transfers. The option about carbon exchange being the primary mechanism for biodiversity maintenance introduces a claim far beyond anything stated or implied in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26CF68K', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geochemist Aisha Farouk''s 2023 analysis of zircon crystals from the Jack Hills formation in Western Australia pushed the estimated age of Earth''s earliest continental crust back to 4.37 billion years. This finding challenged the prevailing model, which held that stable continental material could not have formed until at least 200 million years after the Moon-forming impact. ________ Farouk''s data did not resolve whether the ancient crust formed through volcanic resurfacing of a magma ocean or through an entirely distinct mechanism involving meteorite-delivered silicates, leaving the geophysical community divided on the process even as it accepted the revised timeline.', $lyceon_json$[{"key":"A","text":"In contrast,"},{"key":"B","text":"Furthermore,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"However,"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage first describes how Farouk''s findings successfully pushed back the timeline for continental crust formation and challenged the prevailing model. The final sentence then introduces a limitation: the data could not determine the mechanism by which this ancient crust formed. This represents a concession — an acknowledged gap despite the achievement. "However" correctly signals this shift from accomplishment to limitation. "In contrast" is tempting because it also signals opposition, but it specifically marks a comparison between two distinct subjects or situations, whereas the passage discusses a limitation of the same research — not a contrast with a different study or phenomenon. "Furthermore" would incorrectly suggest that the final sentence builds on the achievement, when it actually qualifies it. "Specifically" would incorrectly suggest the final sentence provides details that elaborate on the revised timeline, when it actually introduces an unresolved question about mechanism.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW283X74P', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The architectural historian Tomasz Kowalczyk has argued that the vaulted ceilings of the fourteenth-century granaries in Gdansk were designed not merely for structural reinforcement but also for acoustic regulation. According to Kowalczyk, the grain merchants who commissioned _______ aware that arched stone surfaces would dampen the reverberations caused by the constant loading and unloading of heavy sacks.', $lyceon_json$[{"key":"A","text":"these buildings were"},{"key":"B","text":"these buildings, were"},{"key":"C","text":"these buildings being"},{"key":"D","text":"these buildings, being"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause beginning with ''the grain merchants who commissioned'' requires a finite verb to complete the predicate. The relative clause ''who commissioned these buildings'' modifies ''merchants,'' and the main verb ''were'' then provides the predicate for the subject ''merchants.'' The choice ''these buildings were'' correctly completes the relative clause and supplies the finite verb. Inserting a comma after ''buildings'' (the choice reading ''these buildings, were'') incorrectly separates the subject from its verb with a single comma, violating standard punctuation conventions. Using the participial ''being'' instead of the finite ''were'' (the choice reading ''these buildings being'') creates a sentence fragment by failing to provide a main verb for the clause. Combining both errors with a comma and a participle (the choice reading ''these buildings, being'') similarly produces a fragment while also introducing a spurious comma.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28IF7ZD', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Groningen have discovered that the Antarctic icefish, Chaenocephalus aceratus, lacks red blood cells entirely — a trait unique among vertebrates. Instead of relying on hemoglobin to transport oxygen, the icefish absorbs oxygen directly through its skin and gills, aided by the exceptionally high oxygen solubility of the frigid Antarctic waters. The fish compensates for the absence of hemoglobin by pumping a larger volume of blood per heartbeat than comparably sized species, using an oversized heart that constitutes nearly three percent of its body mass.', $lyceon_json$[{"key":"A","text":"The Antarctic icefish has evolved unusual physiological features that allow it to survive without red blood cells."},{"key":"B","text":"Cold water contains more dissolved oxygen than warm water, which benefits many Antarctic marine species."},{"key":"C","text":"The icefish's oversized heart is the primary reason it can live in Antarctic waters."},{"key":"D","text":"Most vertebrates depend on hemoglobin for oxygen transport, though some use alternative respiratory pigments."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on how the Antarctic icefish survives without red blood cells through multiple compensatory adaptations: direct oxygen absorption through skin and gills, and an oversized heart. The correct answer captures this central idea. The option about cold water and dissolved oxygen mentions a detail from the passage but misidentifies it as the main point, focusing on a supporting fact rather than the icefish''s adaptations. The option about the oversized heart being the primary reason is only partially correct — the heart is one of several adaptations mentioned, not the sole explanation. The option about most vertebrates using hemoglobin or alternative pigments introduces information not discussed in the passage, which never mentions alternative respiratory pigments.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AU3D3F', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the textile artist Meera Joshi began experimenting with naturally derived pigments in 2017, she found that fabrics dyed with extracts of the indigo plant _______ their color more effectively than those treated with synthetic alternatives, provided the fabrics were pre-soaked in a tannin solution for at least seventy-two hours.', $lyceon_json$[{"key":"A","text":"retained"},{"key":"B","text":"had retained"},{"key":"C","text":"have retained"},{"key":"D","text":"would have retained"}]$lyceon_json$::jsonb, 'A', NULL, E'The main clause describes what Joshi found during her experiments, which began in 2017. The simple past tense ''retained'' correctly matches the past-tense frame established by ''she found that,'' reporting the result of her observations. The past perfect ''had retained'' would indicate an action completed before another past event, but no such prior time frame is established; the retaining of color was contemporaneous with her finding, not anterior to it. The present perfect ''have retained'' incorrectly shifts to a present time frame, breaking the past-tense sequence. The conditional perfect ''would have retained'' implies a hypothetical or counterfactual scenario, but the passage presents Joshi''s finding as an actual observed result, not a hypothetical one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BZQ4LO', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Coral reefs are often called the rainforests of the sea because of their extraordinary biodiversity. Marine biologist Renata Cabral has documented that a single reef system in the Coral Triangle can support over 1,700 species of fish and 600 species of hard coral. Yet Cabral''s own fieldwork in the Banda Sea has revealed that even reefs with high species counts can be functionally fragile: when a few keystone herbivores decline, algal overgrowth can destabilize the entire community within months. Her findings suggest that species richness alone is an inadequate measure of reef resilience.', $lyceon_json$[{"key":"A","text":"It presents a common characterization, provides supporting evidence, then introduces a complication that qualifies the initial claim."},{"key":"B","text":"It describes two competing hypotheses and argues that neither is fully supported by available data."},{"key":"C","text":"It traces the chronological development of a researcher's career from early observations to later conclusions."},{"key":"D","text":"It contrasts the methods used in two different studies and evaluates which produced more reliable results."}]$lyceon_json$::jsonb, 'A', NULL, E'The text opens with the familiar characterization of reefs as biodiversity hotspots, supports it with Cabral''s species-count data, then pivots with "Yet" to introduce her finding that high species counts can mask functional fragility — qualifying the initial claim. The choice about two competing hypotheses is wrong because the text presents one characterization and then complicates it, rather than setting two hypotheses against each other. The choice about chronological career development is wrong because the passage discusses findings topically, not as a biographical timeline. The choice about contrasting methods of two studies is wrong because only Cabral''s research is discussed, and the passage does not compare methodologies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E16DDB', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief profile of the ceramicist Yuto Kaneda for a school arts magazine. The student wants to emphasize how Kaneda''s technique differs from conventional pottery methods. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
