INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EHMS58', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Khoisan rock paintings found in the Tsodilo Hills of Botswana, believed to be among the oldest artistic works in southern Africa, _______ a source of scholarly debate since their formal documentation in 1965.', $lyceon_json$[{"key":"A","text":"have been"},{"key":"B","text":"has been"},{"key":"C","text":"was"},{"key":"D","text":"being"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is the plural noun ''paintings,'' so the verb must agree in number. The phrase ''believed to be among the oldest artistic works in southern Africa'' is a parenthetical that does not change the subject. The present perfect plural form ''have been'' correctly agrees with the plural subject and conveys the ongoing nature of the debate since 1965. The singular ''has been'' fails to agree with the plural subject ''paintings.'' The singular past tense ''was'' both fails in number agreement and incorrectly implies the debate has ended. The participial ''being'' creates a sentence fragment by failing to provide a finite verb.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FZK0UW', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2021 study of deep-sea bioluminescence, marine biologist Kwame Asante observed that certain lanternfish species in the Mozambique Channel adjust the wavelength of their light emissions depending on ambient water clarity. By modifying the ratio of luciferin compounds in their photophores, each _______ its bioluminescent signal to match the optical properties of the surrounding water column.', $lyceon_json$[{"key":"A","text":"species calibrates"},{"key":"B","text":"species calibrate"},{"key":"C","text":"species, calibrating"},{"key":"D","text":"species have calibrated"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the second sentence is ''each species,'' where the pronoun ''each'' is singular and requires a singular verb. The singular present-tense form ''calibrates'' correctly agrees with ''each species'' and matches the present-tense context of the passage describing an ongoing behavior. The plural form ''calibrate'' fails to agree with the singular ''each.'' The choice using a comma and the participial ''calibrating'' creates a sentence fragment by leaving the second sentence without a main verb. The plural present perfect ''have calibrated'' both fails in number agreement with ''each'' and incorrectly shifts the tense to imply a completed action.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GEE4C9', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'During the 1923 excavation of a Sumerian burial site near Ur, archaeologist Leonard Woolley noticed that several clay tablets had been ________ by centuries of groundwater seepage, their cuneiform inscriptions reduced to faint, barely legible impressions.', $lyceon_json$[{"key":"A","text":"eroded"},{"key":"B","text":"concealed"},{"key":"C","text":"replicated"},{"key":"D","text":"distributed"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes clay tablets whose inscriptions have been worn away by water over centuries, leaving only faint impressions. "Eroded" means gradually worn down by natural forces, which directly fits the described physical degradation. "Concealed" means hidden from view, but the tablets were found and examined, not hidden. "Replicated" means copied or reproduced, which contradicts the idea of damage. "Distributed" means spread out or dispersed, which does not describe the physical deterioration of the tablets'' surfaces.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GEO9ZQ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The playwright Esmeralda Vasconcelos drew on Portuguese maritime folklore for her 2019 drama Ondas _______ weaves together the voices of three generations of fisherwomen from the Algarve coast, each confronting the same tempestuous stretch of the Atlantic Ocean.', $lyceon_json$[{"key":"A","text":"Perdidas, which"},{"key":"B","text":"Perdidas which"},{"key":"C","text":"Perdidas. Which"},{"key":"D","text":"Perdidas; which"}]$lyceon_json$::jsonb, 'A', NULL, E'The relative clause beginning with ''which'' is nonrestrictive: it provides additional information about the single play Ondas Perdidas rather than distinguishing it from other plays. Nonrestrictive relative clauses require a comma before ''which.'' The choice using a comma before ''which'' correctly punctuates this nonrestrictive clause. Omitting the comma before ''which'' treats the clause as restrictive, which is incorrect because there is only one play being discussed. Placing a period before ''which'' creates a sentence fragment, since ''which weaves together...'' lacks an independent subject. Using a semicolon before ''which'' is similarly incorrect because what follows is a dependent clause, not an independent clause, and semicolons join independent clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HFM6LT', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JMLG38', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The geochemist Adaora Nnaji recently demonstrated that volcanic basalt formations in northeastern Nigeria contain unusually high concentrations of rare-earth _______ this finding has prompted several mining companies to reassess the region''s commercial potential.', $lyceon_json$[{"key":"A","text":"elements, and"},{"key":"B","text":"elements and"},{"key":"C","text":"elements,"},{"key":"D","text":"elements"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank joins two independent clauses: one about Nnaji''s demonstration and one about mining companies reassessing the region. A comma followed by the coordinating conjunction ''and'' correctly joins two independent clauses. Omitting the comma before ''and'' (the choice reading ''elements and'') fails to properly punctuate the compound sentence with two independent clauses, each having its own subject and verb. Using only a comma (the choice reading ''elements,'') creates a comma splice, which improperly fuses two independent clauses without a conjunction. Omitting both the comma and the conjunction (the choice reading ''elements'') creates a run-on sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K5E2SA', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In her 2019 monograph on Ottoman fiscal administration, historian Elif Batuman Kaya contends that provincial tax collectors in the seventeenth century did not simply extract revenue but served as ________ between the imperial treasury and local agrarian communities, translating centralized directives into arrangements that accommodated regional crop cycles and customary land-use practices.', $lyceon_json$[{"key":"A","text":"intermediaries"},{"key":"B","text":"obstacles"},{"key":"C","text":"patrons"},{"key":"D","text":"spectators"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes tax collectors who bridged two parties — the imperial treasury and local communities — by translating central directives into locally adapted arrangements. "Intermediaries" means go-betweens who facilitate communication or negotiation between two groups, which precisely captures this bridging function. "Obstacles" means barriers that impede progress, but the passage portrays the collectors as facilitating rather than hindering the relationship. "Patrons" means benefactors who provide financial support or protection, but the passage describes a translating and mediating role, not a sponsoring one. "Spectators" means passive onlookers, which contradicts the active role of translating directives and accommodating local practices.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KU683K', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the late Ottoman period, Armenian and Greek photographers in Istanbul pioneered the documentation of archaeological sites across Anatolia, producing thousands of glass-plate negatives that recorded monuments later destroyed or severely damaged during the upheavals of the early twentieth century. Art historian Edhem Eldem has noted that these photographs now constitute an irreplaceable visual archive, since many of the structures they depict no longer exist in their documented form. However, Eldem cautions that the photographs should not be treated as neutral records, because the photographers'' compositional choices — which structures to foreground, which angles to select, which elements to exclude from the frame — inevitably ________', $lyceon_json$[{"key":"A","text":"reflected the aesthetic conventions and cultural priorities of the photographers rather than presenting the sites as they would appear to an unmediated observer."},{"key":"B","text":"were dictated primarily by the technical limitations of glass-plate photography, which required long exposure times and stable lighting conditions."},{"key":"C","text":"have made it difficult for modern archaeologists to determine the precise geographic locations of the sites depicted in the photographs."},{"key":"D","text":"demonstrated that Ottoman-era photographers had received formal training in European artistic traditions during the mid-nineteenth century."}]$lyceon_json$::jsonb, 'A', NULL, E'Eldem''s caution that the photographs are not neutral records, combined with his emphasis on compositional choices like framing and angle selection, points toward the conclusion that these choices reflect the photographers'' perspectives rather than offering an objective view. The option about technical limitations of glass-plate photography introduces a factor not mentioned in the passage, which focuses on deliberate compositional decisions rather than technological constraints. The option about difficulty determining geographic locations does not follow from the discussion of compositional choices. The option about formal European training makes a specific historical claim that is neither stated nor implied by the passage''s discussion of non-neutrality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LBGH1T', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'In the early twentieth century, physicists widely assumed that the interior of the Earth was entirely solid. This view was consistent with seismic wave data available at the time, which showed that compressional waves traveled through the planet''s interior in patterns suggesting a rigid, continuous medium.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NTOM6Q', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, conservationist Hiroko Takeda proposed relocating endangered Iriomote cats to a protected sanctuary on Okinawa. Her colleagues at the Wildlife Preservation Society of _______ the cats'' territorial instincts would make adaptation to an unfamiliar habitat extremely unlikely.', $lyceon_json$[{"key":"A","text":"Japan, however, argued that"},{"key":"B","text":"Japan however argued that"},{"key":"C","text":"Japan, however argued that"},{"key":"D","text":"Japan however, argued that"}]$lyceon_json$::jsonb, 'A', NULL, E'The interruptive adverb ''however'' appears parenthetically within the sentence and must be set off by commas on both sides. The correct choice places commas before and after ''however,'' properly punctuating the parenthetical interruption. Omitting both commas around ''however'' fails to set off the interrupter. Placing a comma only before ''however'' leaves the closing side of the interruption unmarked. Placing a comma only after ''however'' similarly fails to punctuate the opening side of the parenthetical element.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OJ2BSI', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an argumentative essay for an art history seminar. The student wants to challenge the claim that Hilma af Klint was primarily influenced by Theosophy by presenting evidence of an alternative intellectual source for her abstract paintings. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q0S3JF', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Behavioral ecologist Mariana Vasconcelos has argued that the cooperative hunting strategies observed in Harris''s hawks are not merely instinctual but represent a ________ response to shifting prey densities, with the birds adjusting their formation sizes and pursuit angles based on the abundance of desert cottontails in a given season.', $lyceon_json$[{"key":"A","text":"calibrated"},{"key":"B","text":"permanent"},{"key":"C","text":"token"},{"key":"D","text":"coerced"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage emphasizes that the hawks adjust their behavior precisely according to prey densities, making "calibrated" — meaning carefully adjusted or fine-tuned to match specific conditions — the logical completion. "Permanent" means unchanging, which directly contradicts the passage''s emphasis on adjustment and shifting conditions. "Token" means minimal or symbolic, which would undercut the passage''s point that the behavior is a meaningful, substantive adaptation. "Coerced" means forced against one''s will, which implies external compulsion rather than adaptive behavioral flexibility.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QJK61T', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about the ecological role of parrotfish for a marine biology course. The student wants to present a cause-and-effect relationship between parrotfish feeding behavior and reef health. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RF1D6J', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a staple of genetics research for over a century. Its genome was fully sequenced in the year 2000, revealing approximately 13,600 genes — a figure that surprised many scientists who had expected a far larger number. That unexpected finding prompted researchers to investigate how such genomic economy could produce the complex behaviors and developmental patterns observed in the species.', $lyceon_json$[{"key":"A","text":"It introduces a research outcome that motivated further scientific inquiry."},{"key":"B","text":"It challenges the reliability of a widely accepted experimental method."},{"key":"C","text":"It provides biographical context about the scientists involved in the study."},{"key":"D","text":"It summarizes the overall conclusions of a long-running research program."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence presents the surprising gene count (the research outcome) and then states that this finding prompted further investigation, directly linking an outcome to subsequent inquiry. The choice stating it challenges the reliability of an experimental method is wrong because the passage questions the expectation about gene count, not the validity of any method. The choice about biographical context is wrong because no personal details about specific scientists are provided. The choice about summarizing conclusions of a long-running program is wrong because the sentence introduces a single surprising finding, not a comprehensive summary of decades of research.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TL45G6', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V6NHRH', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists studying the decline of Caribbean staghorn coral (Acropora cervicornis) have hypothesized that elevated sea surface temperatures weaken coral immune responses, making the organisms more susceptible to white band disease. To test this hypothesis, a research team collected coral fragments from reefs near Curaçao and exposed them to varying water temperatures in controlled laboratory tanks while monitoring markers of immune function.', $lyceon_json$[{"key":"A","text":"Coral fragments maintained at 31°C showed a 47 percent reduction in phagocytic cell activity compared to fragments maintained at 26°C."},{"key":"B","text":"White band disease was first documented in Caribbean reefs in 1977, several decades before significant ocean warming trends were recorded."},{"key":"C","text":"Staghorn coral populations near Curaçao have declined by 83 percent since 1980, a period during which fishing pressure also increased substantially."},{"key":"D","text":"Coral fragments exposed to lower salinity levels exhibited tissue damage similar to that caused by white band disease."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis states that elevated temperatures weaken coral immune responses, increasing disease susceptibility. A finding showing reduced immune cell activity at higher temperatures directly supports this causal link. The option about white band disease appearing before significant warming would actually undermine the hypothesis by suggesting the disease predates the proposed cause. The option about coral decline alongside increased fishing introduces a confounding variable rather than evidence for the temperature-immunity connection. The option about low salinity causing similar tissue damage addresses a different environmental stressor entirely and does not speak to the temperature-immunity relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W4E842', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economists studying the labor market effects of automation have generally found that while robots and algorithmic systems displace workers in specific occupations, the overall employment level in affected regions often recovers within a decade as new job categories emerge. However, economic historian Carl Benedikt Frey argues that this aggregate recovery obscures a critical distributional problem: the workers who lose jobs to automation are frequently not the same individuals who obtain the newly created positions. Frey points to evidence that displaced manufacturing workers in the American Midwest experienced average earnings declines of 17 percent even fifteen years after their initial job loss, while the new technology-sector positions that emerged in the same regions were filled predominantly by younger workers with different educational backgrounds. This pattern suggests that ________', $lyceon_json$[{"key":"A","text":"the net employment effects of automation may be neutral at the regional level while producing lasting economic harm to the specific workers whose jobs are eliminated."},{"key":"B","text":"automation primarily threatens workers in the manufacturing sector, whereas service-sector workers face minimal risk of displacement."},{"key":"C","text":"regional economic recovery from automation-driven job losses depends more on government retraining programs than on organic market adjustments."},{"key":"D","text":"younger workers benefit from automation because they are more willing to relocate to regions where technology-sector jobs are being created."}]$lyceon_json$::jsonb, 'A', NULL, E'Frey''s argument distinguishes between aggregate recovery (overall employment rebounds) and individual outcomes (displaced workers suffer lasting earnings declines). The passage''s evidence about persistent wage losses for displaced workers alongside new jobs filled by different people supports the inference that regional-level neutrality masks individual-level harm. The option narrowing the threat to manufacturing workers goes beyond the passage, which uses manufacturing as an example but does not claim service-sector workers face minimal risk. The option about government retraining programs introduces a policy prescription not discussed or implied in the passage. The option about younger workers relocating misreads the passage, which states that new positions in the same regions were filled by younger workers with different backgrounds, not that younger workers relocated to those regions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WBFJQ4', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Industrial ecologist Maren Lindqvist has argued that municipal composting programs, while effective at diverting organic waste from landfills, inadvertently concentrate heavy metals such as cadmium and chromium in the resulting compost when residents include treated wood products and certain dyed textiles in their green bins. Lindqvist''s lab tests showed cadmium levels in compost from three Nordic cities exceeded European agricultural safety thresholds by 40 to 70 percent. ________ her proposed solution — mandatory preprocessing that uses X-ray fluorescence scanners to reject contaminated feedstock — would add an estimated \\$23 per metric ton to municipal composting costs, a figure that several city waste authorities have called prohibitively expensive.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"That said,"},{"key":"C","text":"To illustrate,"},{"key":"D","text":"Likewise,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes a problem (heavy metal contamination in municipal compost) and provides supporting evidence (cadmium levels exceeding safety thresholds). The final sentence then introduces a complication regarding the proposed solution: the fix exists but is considered too expensive. This represents a concessive turn — acknowledging a drawback to an otherwise logical remedy. "That said" correctly signals this kind of concession, where the writer pivots from presenting the problem and its evidence to qualifying the feasibility of the solution. "As a result" would incorrectly frame the final sentence as a direct consequence of the cadmium findings, but the sentence introduces a new complication about cost rather than a logical outcome of contamination data. "To illustrate" would incorrectly suggest the final sentence exemplifies the contamination problem, when it actually introduces a separate issue about economic feasibility. "Likewise" would incorrectly imply a parallel situation, when the final sentence introduces a tension rather than a similarity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X5FLC3', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively support the claim presented in the text?', E'Some scholars of Victorian literature argue that Charlotte Brontë''s novel Villette (1853) represents a more radical challenge to gender conventions than her better-known Jane Eyre (1847). While Jane Eyre concludes with the protagonist''s marriage, Villette''s narrator, Lucy Snowe, remains fundamentally ambiguous about her romantic fate, and the novel''s final pages deliberately withhold the conventional closure that Victorian readers expected. These scholars contend that Villette''s refusal of narrative resolution reflects Brontë''s deepening skepticism about whether marriage could serve as an adequate framework for representing women''s psychological complexity.', $lyceon_json$[{"key":"A","text":"\"In Villette, Brontë dismantles the marriage plot not by attacking it directly but by allowing it to dissolve into uncertainty, forcing readers to confront the inadequacy of romantic resolution as a measure of female fulfillment.\""},{"key":"B","text":"\"Brontë's prose style in Villette is notably more experimental than in Jane Eyre, incorporating dream sequences and hallucinatory imagery that anticipate modernist techniques by half a century.\""},{"key":"C","text":"\"Lucy Snowe is among the least likable narrators in Victorian fiction, and Brontë appears to have deliberately constructed her as a figure who resists reader sympathy.\""},{"key":"D","text":"\"The commercial failure of Villette relative to Jane Eyre suggests that Victorian audiences were unwilling to engage with novels that lacked compelling romantic subplots.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The passage claims that Villette challenges gender conventions more radically than Jane Eyre by refusing narrative closure through marriage and reflecting Brontë''s skepticism about marriage as a framework for women''s complexity. The correct quotation directly addresses this claim by discussing how Villette dismantles the marriage plot through uncertainty, connecting this to the inadequacy of romantic resolution for representing female experience. The quotation about experimental prose style discusses a different aspect of the novel — its literary technique — rather than its challenge to gender conventions. The quotation about Lucy Snowe''s likability addresses characterization but not the novel''s stance on marriage or gender norms. The quotation about commercial failure concerns audience reception and does not support the specific claim about Villette''s challenge to gender conventions through narrative structure.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
